/**
 * Keeps Excalidraw 100% unmodified while making it air-gap safe.
 *
 * Excalidraw builds its @font-face sources as
 *   https://esm.sh/@excalidraw/excalidraw@<ver>/dist/prod/fonts/<Family>/<file>.woff2
 * Instead of patching that code, we wrap the global FontFace constructor and answer those
 * URLs from the fonts embedded in the page (<script id="timelapse-fonts">, a map of
 * "<Family>/<file>.woff2" -> base64, generated by build.mjs straight from the package).
 * The URL is therefore never requested. A font that is missing from the map is reported
 * loudly (console + the CSP blocks the CDN request), never silently.
 */
const el = document.getElementById("timelapse-fonts");
const fonts: Record<string, string> = el?.textContent ? JSON.parse(el.textContent) : {};
const Native = window.FontFace;
const URL_RE = /url\(\s*(['"]?)[^)'"]*\/fonts\/([^)'"/]+\/[^)'"/]+\.woff2)\1\s*\)/g;

class OfflineFontFace extends Native {
  constructor(family: string, source: string | BufferSource, descriptors?: FontFaceDescriptors) {
    if (typeof source === "string") {
      source = source.replace(URL_RE, (match, _q, rel: string) => {
        const b64 = fonts[rel];
        if (b64) return `url(data:font/woff2;base64,${b64})`;
        console.error(`[timelapse] font not embedded: ${rel}`);
        return match;
      });
    }
    super(family, source, descriptors);
  }
}
window.FontFace = OfflineFontFace as typeof FontFace;
